const express = require('express');
const { z } = require('zod');
const { DynamicStructuredTool } = require('@langchain/core/tools');
const { authMiddleware } = require('../middleware/auth');
const { DeviceTelemetry } = require('../services/telemetry');
const { FleetDevice } = require('../models/device');

const app = express();
app.use(express.json());

app.post('/api/fleet/tools/telemetry-export', authMiddleware, async (req, res) => {
  const { toolParams } = req.body;
  try {
    const { deviceSerial, startDate, endDate } = toolParams || {};

    // Validate that the authenticated user owns or manages this device
    const device = await FleetDevice.findOne({
      where: { serialNumber: deviceSerial, ownerFleetId: req.user.fleetId }
    });

    if (!device) {
      return res.status(403).json({ error: 'Access denied: Device does not belong to your fleet' });
    }

    const exportDeviceTelemetryTool = new DynamicStructuredTool({
      name: 'export_device_telemetry',
      description: 'Exports GPS breadcrumbs and sensor history for a specified vehicle or tracker',
      schema: z.object({
        deviceSerial: z.string(),
        startDate: z.string(),
        endDate: z.string()
      }),
      func: async ({ deviceSerial, startDate, endDate }) => {
        const records = await DeviceTelemetry.getHistory(deviceSerial, startDate, endDate);
        return JSON.stringify(records);
      }
    });

    const data = await exportDeviceTelemetryTool.invoke(toolParams);
    res.json({ success: true, history: JSON.parse(data) });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

app.listen(8120);
